INSERT INTO `settings` (`id`, `type`, `name`, `description`, `link`, `image`, `status`, `created_at`, `updated_at`) VALUES
(11, 12, 'How to Betting', '<p style=\"color: #00ff00; font-weight: bold;\">2. How to Betting</p>\r\n\r\n<ul style=\"color: #ffffff;\">\r\n    <li>Participation in games on BDG Cassino involves financial risk.</li>\r\n    <li>You may lose some or all of your money while playing games.</li>\r\n    <li>Play responsibly and only with funds you can afford to lose.</li>\r\n    <li>Ensure you understand the game rules before placing bets.</li>\r\n    <li>Check your account balance before and after placing a bet.</li>\r\n</ul>', '', 'images/beginner_guide/betting.png', 0, '2025-07-18 05:46:09', '2025-07-18 05:46:09'),
(12, 13, 'How to recharge', '<p style=\"color: #00ff00; font-weight: bold;\">3. How to recharge</p>\r\n\r\n<p style=\"color: #ffffff;\">\r\n    Click Wallet Icon, Click The Recharge Button, and we have five ways to make a recharge (BANK TRANSFER, E-WALLET)\r\n</p>\r\n', '', 'images/beginner_guide/recharge.png', 0, '2025-07-18 05:47:45', '2025-07-18 05:47:45'),
(13, 14, 'How to Withdraw', '<p style=\"color: #00ff00; font-weight: bold;\">4. How to Withdraw</p>\r\n\r\n<p style=\"color: #ffffff;\">\r\n    Click Wallet Icon, Click Withdraw Button.\r\n</p>\r\n\r\n<ul style=\"color: #ffffff;\">\r\n    <li>Enter withdraw amount</li>\r\n    <li>Make Sure Your Total Bet Until Zero</li>\r\n    <li>Select Your Bank Account Or Add Your Bank Account</li>\r\n    <li>Input Amount You Want To Withdraw</li>\r\n    <li>Input Your Login Password</li>\r\n</ul>\r\n', '', 'images/beginner_guide/withdraw.png', 0, '2025-07-18 05:49:22', '2025-07-18 05:49:22'),
(16, 15, 'Orders', '<p style=\"color: #00ff00; font-weight: bold;\">5. Orders</p>\r\n\r\n<p style=\"color: #ffffff;\">\r\n    When The Betting Complete You Can Click My Game Record To See Your Bet Record, You Can Check The Chart Trend.\r\n</p>\r\n', '', 'images/beginner_guide/orders.png', 0, '2025-07-18 05:53:24', '2025-07-18 05:53:24'),
(17, 16, 'Promotion', '<p style=\"color: #00ff00; font-weight: bold;\">6. Promotion</p>\n\n<ul style=\"color: #ffffff; list-style-type: none; padding-left: 0;\">\n    <li>- If you have a downline or referral member use your own link to register and if they make a recharge you can claim a reward. The agent will get a minimum commission of 0.6% (level 1) and 0.18% (level 2) from each transaction that is done by the referral (Added every day at 00:30 AM). If the accumulated transactions of the referral reach a certain target, the agent will get an additional bonus with the following rebates.</li>\n    <li>- You Can Click The Sharing Invitation Poster To See The Barcode</li>\n</ul>\n', '', 'images/beginner_guide/pramotation.png', 0, '2025-07-18 05:56:44', '2025-07-18 05:56:44'),
(18, 17, 'Account security', '<p style=\"color: #00ff00; font-weight: bold;\">7. Account security</p>\n\n<p style=\"color: #ffffff;\">\n    Go To My Icon, Click Setting Icon.\n</p>\n\n<ul style=\"color: #ffffff; list-style-type: none; padding-left: 0;\">\n    <li>- Click Login Password.</li>\n    <li>- Re-Enter Your Login Password.</li>\n    <li>- Enter Strongest New Password, and Confirm Your Password.</li>\n    <li>- Click Save Changes.</li>\n</ul>\n', '', 'images/beginner_guide/accounts.png', 0, '2025-07-18 05:58:27', '2025-07-18 05:58:27'),
(19, 18, 'Forgot Password', '<p style=\"color: #00ff00; font-weight: bold;\">8. Forgot Password</p>\n\n<p style=\"color: #ffffff;\">\n    If You Forget Your Login Password, Please Contact Customer Service Immediately.\n</p>\n\n\n', '', 'images/beginner_guide/forget.png', 0, '2025-07-18 06:00:30', '2025-07-18 06:00:30'),
(20, 19, 'App download', '<p style=\"color: #00ff00; font-weight: bold;\">9. App download</p>\n\n<p style=\"color: #ffffff;\">\n    Click top right corner download icon, you can download the app and easy to use.\n</p>\n', '', 'images/beginner_guide/appdownload.png', 0, '2025-07-18 06:00:30', '2025-07-18 06:00:30'),
(21, 20, 'About', '<p style=\"color: #00ff00; font-weight: bold;\">10. About</p>\n<p style=\"color: #ffffff;\">\n    Click About for more details regarding Privacy Policy and Risk Disclosure Agreement.\n</p>\n', '', 'images/beginner_guide/aboutus.png', 0, '2025-07-18 06:03:47', '2025-07-18 06:03:47'),
(22, 21, 'Gift', '<p style=\"color: #00ff00; font-weight: bold;\">11. Gift</p>\n<p style=\"color: #ffffff;\">\n    - Click Gift Exchange<br>\n    - Input The Unique Code To Redemption Code The Money<br>\n    - Click Receive\n</p>\n', '', 'images/beginner_guide/gift.png', 0, '2025-07-18 06:03:47', '2025-07-18 06:03:47'),
(23, 11, 'How to Register', '<p style=\"color: #00ff00; font-weight: bold;\">1. How to Register</p>\n<p style=\"color: #ffffff;\">\n    - Fill Your Phone Number<br>\n    - Set Your Own Password (6 letters)<br>\n    - Confirm The Password<br>\n    - Fill Your Recommendation Code<br>\n    - Click I Have Read And Agree<br>\n    - Click Register\n</p>\n', '', 'images/beginner_guide/register.png', 0, '2025-07-18 06:05:12', '2025-07-18 06:05:12');
